import { createRearrangeableListbox, type RearrangeableListbox } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import {
  createEffect,
  createSignal,
  createUniqueId,
  For,
  onCleanup,
  Show,
  untrack,
} from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** One row of the list: its words, and the line under them. */
export interface ReorderItem {
  /** The label, which is also the row's name for a reader. */
  readonly label: string;
  /** A second line: what the row is, beside what it is called. */
  readonly description?: string | undefined;
}

export interface ReorderProps {
  /**
   * The rows, in the order they start in. Read once, when the primitive is created: the option id is the index here, so
   * an item's identity survives every move. A page that replaces the set makes a new `<Reorder>`.
   */
  readonly items: ReadonlyArray<ReorderItem>;
  /** The list's accessible name. @default "Reorderable list" */
  readonly label?: string | undefined;
  /** The rows in their new order, after the reader moved one. */
  readonly onReorder?: ((items: ReadonlyArray<ReorderItem>) => void) | undefined;
  /** The primitive, once: a page that drives the order itself. */
  readonly onReady?: ((listbox: RearrangeableListbox) => void) | undefined;
  /** The line under the list; left out, the drag and the keys in one sentence. */
  readonly hint?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_LABEL = "Reorderable list";
const DEFAULT_HINT =
  "Drag a row by its handle, or focus the list and press Alt+↑ or Alt+↓ to move the focused row.";

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2));

// The list is its own frame: the surface, the border and the radius are the kit's, and the dark mode moves the tokens
// underneath. It is the tab stop, so the focus ring is the list's and not a row's.
const listClass = css.cn(
  css.display("grid"),
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.bg(t.color.surface),
  css.color(t.color.text),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.fontSize(t.font.size),
  css.userSelect("none"),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

// A row is the whole option: the handle, the two lines of text and the position number. The selected look is the
// primitive's `aria-selected`, which in a single-select listbox follows the focus; the dragged row is lifted.
const rowClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns("auto minmax(0, 1fr) auto"),
  css.alignItems("center"),
  css.gap(t.space._3),
  css.minHeight(t.space._9),
  css.padding(t.space._2, t.space._3),
  css.boxSizing("border-box"),
  css.position("relative"),
  css.bg(t.color.surface),
  css.borderBottom("1px solid", t.color.border),
  css.outline("none"),
  css.lastChild(css.borderBottom("none")),
  css.hover(css.bg(t.color.buttonBackground)),
  css.attr("aria-selected", "true")(
    css.bg(t.color.buttonBackgroundPressed),
    css.hover(css.bg(t.color.buttonBackgroundPressed)),
  ),
  css.attr("data-dragging", "true")(
    css.bg(t.color.surface),
    css.borderColor(t.color.borderHover),
    css.boxShadow(t.shadow.popover),
    css.transform("translateY(-1px)"),
    css.zIndex("1"),
    css.hover(css.bg(t.color.surface)),
  ),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out, transform 120ms ease-out"),
  ),
);

const handleClass = css.cn(
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.width(t.space._6),
  css.height(t.space._8),
  css.flexShrink("0"),
  css.borderRadius(t.radius.sm),
  css.color(t.color.muted),
  css.cursor("move"),
  css.touchAction("none"),
  css.hover(css.bg(t.color.buttonBackground), css.color(t.color.text)),
);

const glyphClass = css.cn(css.fill("currentColor"));

const textClass = css.cn(css.display("grid"), css.gap("2px"), css.minWidth("0"));

const labelClass = css.cn(
  css.overflow("hidden"),
  css.whiteSpace("nowrap"),
  css.textOverflow("ellipsis"),
);

const descriptionClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.overflow("hidden"),
  css.whiteSpace("nowrap"),
  css.textOverflow("ellipsis"),
);

const positionClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  css.fontVariantNumeric("tabular-nums"),
);

const statusClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
);

const hintClass = css.cn(
  css.margin("0"),
  css.padding("0", t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
);

/**
 * A reorderable list, styled: `createRearrangeableListbox` owns the option set and its order, the listbox's
 * `role` / `tabindex` / `aria-activedescendant`, each option's `role` and `aria-selected`, the focus of the list, the
 * arrows, Home and End, and Alt+↑ / Alt+↓ (the primitive's own reorder keys). The skin owns the frame (surface, border,
 * radius and the tokens in light and dark), the handle and its pointer drag, the position numbers, the selected, hover
 * and dragged looks, the focus ring, the reduced-motion rules, the polite status line that says where a row landed,
 * and `onReorder`.
 *
 * The primitive models two lists that share one option set; this starter renders the first one only, so the transfer
 * keys (Enter and Delete) have nowhere to go and are ignored. A page that needs the second list renders
 * `listProps("b")` beside it; a page that only reorders does not.
 */
export const Reorder = (props: ReorderProps): JSX.Element => {
  const labels = props.items.map((item) => item.label);
  const count = labels.length;
  const hintId = createUniqueId();

  const listbox = createRearrangeableListbox({
    items: labels,
    labels: { a: props.label ?? DEFAULT_LABEL, b: "" },
  });
  untrack(() => props.onReady)?.(listbox);

  /** The row's data; the option id is the item's index in the list the page passed. */
  const itemAt = (id: number): ReorderItem => props.items[id] ?? { label: String(id + 1) };

  const order = (): ReadonlyArray<number> => listbox.order("a");

  const [announced, setAnnounced] = createSignal(
    `Order: ${untrack(order)
      .map((id) => itemAt(id).label)
      .join(", ")}.`,
  );
  // The order is the list's identity: a move changes it, and the status line and `onReorder` follow from it. The first
  // run is the order the list mounted with, so it neither announces a move nor calls `onReorder`.
  let last: string | undefined;
  createEffect(
    () => order().join(","),
    (key) => {
      if (last === undefined) {
        last = key;
        return;
      }
      if (last === key) {
        return;
      }
      last = key;
      const ids = untrack(order);
      const active = untrack(() => listbox.active("a"));
      if (active !== null) {
        const position = ids.indexOf(active);
        if (position >= 0) {
          setAnnounced(
            `Moved ${itemAt(active).label} to position ${position + 1} of ${ids.length}.`,
          );
        }
      }
      untrack(() => props.onReorder)?.(ids.map(itemAt));
    },
  );

  let list: HTMLDivElement | undefined;

  /** The primitive says where the order is; the rows are the DOM, and the move is one step at a time. */
  const moveTo = (id: number, target: number): void => {
    let from = order().indexOf(id);
    const to = order().indexOf(target);
    while (from >= 0 && to >= 0 && from !== to) {
      listbox.move(from > to ? "up" : "down");
      const next = order().indexOf(id);
      if (next === from) {
        return;
      }
      from = next;
    }
  };

  const [dragging, setDragging] = createSignal<number | null>(null);

  const endDrag = (): void => {
    setDragging(null);
    window.removeEventListener("pointerup", endDrag);
    window.removeEventListener("pointercancel", endDrag);
  };

  onCleanup(endDrag);

  /** The handle is the pointer's way in: it makes the row the primitive's active option, then drags it. */
  const startDrag =
    (id: number) =>
    (event: PointerEvent): void => {
      if (event.button !== 0) {
        return;
      }
      event.preventDefault();
      // a drag is an interaction with the list, so the list keeps the focus and the active row follows the row
      list?.focus();
      listbox.optionProps(id).onClick();
      setDragging(id);
      window.addEventListener("pointerup", endDrag);
      window.addEventListener("pointercancel", endDrag);
    };

  /** The row under the pointer is the target: the dragged row steps to it. */
  const overRow = (event: PointerEvent): void => {
    const id = dragging();
    if (id === null) {
      return;
    }
    const over = Number((event.currentTarget as HTMLElement).dataset["id"]);
    if (Number.isNaN(over) || over === id) {
      return;
    }
    moveTo(id, over);
  };

  // The primitive's Enter and Delete transfer the focused option to the second list. This starter renders one list, so
  // there is nowhere to transfer to, and the order is what a reader is changing.
  const onKeyDown = (event: KeyboardEvent): void => {
    if (event.key === "Enter" || event.key === "Delete") {
      event.preventDefault();
      return;
    }
    listbox.listProps("a").onKeyDown(event);
  };

  return (
    <div data-part="reorder-root" class={css.cn(rootClass, props.class)}>
      <div
        {...listbox.listProps("a")}
        data-part="reorder-list"
        aria-describedby={hintId}
        class={listClass}
        ref={(node: HTMLDivElement) => {
          list = node;
        }}
        onKeyDown={onKeyDown}
      >
        <For each={order()}>
          {(id, index) => (
            <div
              {...listbox.optionProps(id)}
              data-part="reorder-row"
              data-id={id}
              data-dragging={dragging() === id ? "true" : "false"}
              aria-posinset={index() + 1}
              aria-setsize={count}
              class={rowClass}
              onPointerMove={overRow}
            >
              <span
                data-part="reorder-handle"
                aria-hidden="true"
                class={handleClass}
                onPointerDown={startDrag(id)}
              >
                <svg viewBox="0 0 10 16" width="10" height="16" class={glyphClass}>
                  <For each={[3, 8, 13]}>
                    {(y) => (
                      <>
                        <circle cx="3" cy={y} r="1.3" />
                        <circle cx="7" cy={y} r="1.3" />
                      </>
                    )}
                  </For>
                </svg>
              </span>
              <span data-part="reorder-text" class={textClass}>
                <span data-part="reorder-label" class={labelClass}>
                  {itemAt(id).label}
                </span>
                <Show when={itemAt(id).description}>
                  {(description) => (
                    <span data-part="reorder-description" class={descriptionClass}>
                      {description()}
                    </span>
                  )}
                </Show>
              </span>
              <span data-part="reorder-position" aria-hidden="true" class={positionClass}>
                {index() + 1}
              </span>
            </div>
          )}
        </For>
      </div>
      <p data-part="reorder-status" role="status" aria-live="polite" class={statusClass}>
        {announced()}
      </p>
      <p id={hintId} data-part="reorder-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";

import { Reorder, type ReorderItem } from "./reorder.tsx";

/**
 * Six sections of a home screen, in the order the demo starts them. The description is the one line a row shows under
 * its label; a row that has none still reads as a row.
 */
export const REORDER_ITEMS: ReadonlyArray<ReorderItem> = [
  { label: "Home", description: "The dashboard, first thing in the morning" },
  { label: "Search", description: "Find a track or a station by name" },
  { label: "Library", description: "Saved albums, playlists and shows" },
  { label: "Radio", description: "Live stations and the shows on now" },
  { label: "Podcasts", description: "New episodes of the shows you follow" },
  { label: "Settings", description: "Playback, downloads and the account" },
];

/** The list's accessible name: what these rows order. */
export const REORDER_LABEL = "Home sections";

/** The one sentence the demo says about the drag and the keys. */
export const REORDER_HINT =
  "Drag a row by the dots, or focus the list and press Alt+↑ / Alt+↓ to move the focused row; the number on the right and the status line follow it.";

export interface ReorderExampleProps {
  readonly class?: string | undefined;
  readonly onReorder?: ((items: ReadonlyArray<ReorderItem>) => void) | undefined;
}

/**
 * The starter in ordinary use: the sections of a home screen, each with its handle and its place number. A page copies
 * this and swaps `REORDER_ITEMS` for its own rows and `onReorder` for its own save.
 */
export const ReorderExample = (props: ReorderExampleProps): JSX.Element => (
  <Reorder
    class={props.class}
    items={REORDER_ITEMS}
    label={REORDER_LABEL}
    hint={REORDER_HINT}
    onReorder={props.onReorder}
  />
);

/** What a mounted demo hands the test: where it lives, the last order a page would have saved, and a teardown. */
export interface MountedReorder {
  readonly root: HTMLElement;
  /** The labels of the rows as the page last heard them. */
  readonly order: () => ReadonlyArray<string>;
  /** Every `onReorder` the host received, oldest first. */
  readonly calls: () => ReadonlyArray<ReadonlyArray<string>>;
  readonly dispose: () => void;
}

/** Mounts the styled list at the demo's width. The primitive owns the order; the host only hears it. */
export const mountReorder = (): MountedReorder => {
  const root = document.createElement("div");
  root.style.width = "32rem";
  document.body.append(root);
  const [order, setOrder] = createSignal(REORDER_ITEMS.map((item) => item.label));
  const calls: string[][] = [];
  const dispose = render(
    () => (
      <ReorderExample
        onReorder={(items) => {
          const labels = items.map((item) => item.label);
          calls.push(labels);
          setOrder(labels);
        }}
      />
    ),
    root,
  );
  return {
    root,
    order,
    calls: () => calls,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { REORDER_LABEL, type MountedReorder, mountReorder } from "./reorder.fixture";

// @cssints/headless walks `createRearrangeableListbox` against its Quint spec in
// test/listbox-rearrangeable.browser.test.tsx, so that file is the primitive's oracle. This file is the skin's: it mounts
// the starter in a real Chromium, reads the listbox the primitive built, and drags and keys the rows the way a reader
// does. The starter renders one of the primitive's two lists, so the transfer keys have nowhere to go and the count
// never changes: that is the skin's decision, and it is checked here.

/** Solid 2 applies setters and the primitive's effects on later turns. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const live: MountedReorder[] = [];

const mounted = (): MountedReorder => {
  const instance = mountReorder();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`reorder: no ${selector}`);
  }
  return element;
};

const list = (root: ParentNode): HTMLElement => required(root, '[data-part="reorder-list"]');

const rows = (root: ParentNode): ReadonlyArray<HTMLElement> => [
  ...root.querySelectorAll<HTMLElement>('[data-part="reorder-row"]'),
];

const labelOf = (row: HTMLElement): string =>
  required(row, '[data-part="reorder-label"]').textContent ?? "";

const labels = (root: ParentNode): ReadonlyArray<string> => rows(root).map(labelOf);

const rowByLabel = (root: ParentNode, label: string): HTMLElement => {
  const row = rows(root).find((element) => labelOf(element) === label);
  if (row === undefined) {
    throw new Error(`reorder: no row ${label}`);
  }
  return row;
};

const status = (root: ParentNode): HTMLElement => required(root, '[data-part="reorder-status"]');

/** A key on the focused listbox, as a reader's would arrive. */
const press = async (element: HTMLElement, key: string, alt = false): Promise<void> => {
  element.dispatchEvent(
    new KeyboardEvent("keydown", { key, altKey: alt, bubbles: true, cancelable: true }),
  );
  await settle();
};

const pointer = (element: EventTarget, type: string, buttons: number): void => {
  element.dispatchEvent(
    new PointerEvent(type, {
      bubbles: true,
      cancelable: true,
      composed: true,
      pointerId: 1,
      pointerType: "mouse",
      isPrimary: true,
      button: 0,
      buttons,
    }),
  );
};

/** A drag from one row's handle onto another row: down, over the target, up. */
const drag = async (from: HTMLElement, onto: HTMLElement): Promise<void> => {
  pointer(required(from, '[data-part="reorder-handle"]'), "pointerdown", 1);
  await settle();
  pointer(onto, "pointermove", 1);
  await settle();
  pointer(window, "pointerup", 0);
  await settle();
};

describe("Reorder", () => {
  it("is a named single-select listbox whose rows state their place", async () => {
    const { root } = mounted();
    await settle();

    const element = list(root);
    expect(element.getAttribute("role")).toBe("listbox");
    expect(element.getAttribute("aria-label")).toBe(REORDER_LABEL);
    expect(element.getAttribute("aria-multiselectable")).toBe("false");
    expect(element.tabIndex).toBe(0);

    const all = rows(root);
    expect(all).toHaveLength(6);
    for (const [index, row] of all.entries()) {
      expect(row.getAttribute("role")).toBe("option");
      expect(row.getAttribute("aria-posinset")).toBe(String(index + 1));
      expect(row.getAttribute("aria-setsize")).toBe("6");
      expect(row.getAttribute("aria-selected")).toBe("false");
    }
    // the option ids are the primitive's (the index in the list the page passed), one per row
    expect(new Set(all.map((row) => row.id)).size).toBe(6);

    // the status line is polite and already says the order the demo starts in
    expect(status(root).getAttribute("role")).toBe("status");
    expect(status(root).getAttribute("aria-live")).toBe("polite");
    expect(status(root).textContent).toBe(
      "Order: Home, Search, Library, Radio, Podcasts, Settings.",
    );

    // the first row is the option the primitive's tab stop names once the list has the focus
    element.focus();
    await settle();
    expect(element.getAttribute("aria-activedescendant")).toBe(all[0]?.id);
    expect(all[0]?.getAttribute("aria-selected")).toBe("true");
  });

  it("reorders by dragging a row's handle onto another row, and the host hears the new order", async () => {
    const { root, order, calls } = mounted();
    await settle();

    const library = rowByLabel(root, "Library");
    const home = rowByLabel(root, "Home");
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);

    pointer(required(library, '[data-part="reorder-handle"]'), "pointerdown", 1);
    await settle();
    // the row is lifted, and the list has the focus and the active option
    expect(library.getAttribute("data-dragging")).toBe("true");
    expect(document.activeElement).toBe(list(root));
    expect(list(root).getAttribute("aria-activedescendant")).toBe(library.id);

    pointer(home, "pointermove", 1);
    await settle();
    pointer(window, "pointerup", 0);
    await settle();

    expect(labels(root)).toEqual(["Library", "Home", "Search", "Radio", "Podcasts", "Settings"]);
    expect(rows(root)).toHaveLength(6);
    expect(rowByLabel(root, "Library").getAttribute("data-dragging")).toBe("false");
    expect(rowByLabel(root, "Library").getAttribute("aria-posinset")).toBe("1");
    expect(rowByLabel(root, "Library").getAttribute("aria-selected")).toBe("true");
    // the focus stays in the list, and the option it names is the row that moved
    expect(document.activeElement).toBe(list(root));
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rowByLabel(root, "Library").id);

    // the page heard the order once, and the status line says where the row landed
    expect(calls()).toEqual([["Library", "Home", "Search", "Radio", "Podcasts", "Settings"]]);
    expect(order()).toEqual(["Library", "Home", "Search", "Radio", "Podcasts", "Settings"]);
    expect(status(root).textContent).toBe("Moved Library to position 1 of 6.");
  });

  it("moves the focused row with Alt+Arrow, announces it, and keeps the focus on it", async () => {
    const { root, order } = mounted();
    await settle();

    const element = list(root);
    element.focus();
    await settle();
    // down to Library, the third row
    await press(element, "ArrowDown");
    await press(element, "ArrowDown");
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rowByLabel(root, "Library").id);

    await press(element, "ArrowUp", true);
    expect(labels(root)).toEqual(["Home", "Library", "Search", "Radio", "Podcasts", "Settings"]);
    const library = rowByLabel(root, "Library");
    expect(library.getAttribute("aria-posinset")).toBe("2");
    expect(library.getAttribute("aria-selected")).toBe("true");
    // the primitive keeps the row active, the skin keeps the focus in the list, and the two agree
    expect(list(root).getAttribute("aria-activedescendant")).toBe(library.id);
    expect(document.activeElement).toBe(element);
    expect(status(root).textContent).toBe("Moved Library to position 2 of 6.");
    expect(order()).toEqual(["Home", "Library", "Search", "Radio", "Podcasts", "Settings"]);

    await press(element, "ArrowDown", true);
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rowByLabel(root, "Library").id);
    expect(status(root).textContent).toBe("Moved Library to position 3 of 6.");

    // a plain arrow moves the cursor; it does not reorder
    await press(element, "ArrowUp");
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rowByLabel(root, "Search").id);
  });

  it("jumps to the ends with Home and End, and the order and the count survive", async () => {
    const { root } = mounted();
    await settle();

    const element = list(root);
    element.focus();
    await settle();

    await press(element, "End");
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rows(root).at(-1)?.id);
    expect(rows(root).at(-1)?.getAttribute("aria-posinset")).toBe("6");

    // the last row cannot move down, and the first cannot move up: the order stays
    await press(element, "ArrowDown", true);
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);

    await press(element, "Home");
    expect(list(root).getAttribute("aria-activedescendant")).toBe(rows(root)[0]?.id);
    await press(element, "ArrowUp", true);
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);

    // the primitive's transfer keys have no second list here: Enter and Delete change nothing
    await press(element, "ArrowDown");
    await press(element, "Enter");
    await press(element, "Delete");
    expect(labels(root)).toEqual(["Home", "Search", "Library", "Radio", "Podcasts", "Settings"]);
    expect(rows(root)).toHaveLength(6);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
